51	@@ -0,0 +1,601 @@
52	+// Luanti
53	+// SPDX-License-Identifier: LGPL-2.1-or-later
54	+
55	+// Behavioural checks on how nodes are drawn and outlined: the mesh the map
56	+// block mesh generator produces for small arrangements of nodes, and the
57	+// boxes a node reports for drawing, selection and collision. Every check
58	+// looks at the generated geometry (positions, texture coordinates, which
59	+// texture a face uses) or at the returned boxes, never at how the code gets
60	+// there.
61	+
62	+#include <catch.h>
63	+
64	+#include <algorithm>
65	+#include <cmath>
66	+#include <vector>
67	+
68	+#include "dummygamedef.h"
69	+#include "itemdef.h"
70	+#include "nodedef.h"
71	+#include "mapnode.h"
72	+#include "light.h"
73	+#include "client/content_mapblock.h"
74	+#include "client/mapblock_mesh.h"
75	+#include "client/meshgen/collector.h"
76	+
77	+namespace {
78	+
79	+constexpr float H = BS / 2.0f;
80	+constexpr float EPS = 1e-3f;
81	+
82	+class DrawGameDef : public DummyGameDef {
83	+public:
84	+	NodeDefManager *nodes() { return const_cast<NodeDefManager *>(m_nodedef); }
85	+
86	+	content_t add(const ContentFeatures &f)
87	+	{
88	+		ItemDefinition itemdef;
89	+		itemdef.type = ITEM_NODE;
90	+		itemdef.name = f.name;
91	+		itemdef.description = f.name;
92	+		static_cast<IWritableItemDefManager *>(m_itemdef)->registerItem(itemdef);
93	+		return nodes()->set(f.name, f);
94	+	}
95	+
96	+	void finalize() { nodes()->resolveCrossrefs(); }
97	+};
98	+
99	+void setLightTable()
100	+{
101	+	u8 table[LIGHT_SUN + 1] = {
102	+		0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
103	+		0x88, 0x99, 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF,
104	+	};
105	+	memcpy(const_cast<u8 *>(light_decode_table), table, sizeof(table));
106	+}
107	+
108	+bool near(v3f a, v3f b, float tol)
109	+{
110	+	return std::fabs(a.X - b.X) <= tol && std::fabs(a.Y - b.Y) <= tol && std::fabs(a.Z - b.Z) <= tol;
111	+}
112	+
113	+bool near(v2f a, v2f b, float tol)
114	+{
115	+	return std::fabs(a.X - b.X) <= tol && std::fabs(a.Y - b.Y) <= tol;
116	+}
117	+
118	+struct Tri {
119	+	u32 texture;
120	+	video::S3DVertex v[3];
121	+};
122	+
123	+struct Placed {
124	+	v3s16 pos;
125	+	MapNode node;
126	+};
127	+
128	+// Generates the mesh of a side x side x side block holding `placed`
129	+// (everything else, including a one node border, is air) and returns every
130	+// triangle together with the texture it is drawn with.
131	+std::vector<Tri> render(DrawGameDef &gd, const std::vector<Placed> &placed, s16 side)
132	+{
133	+	setLightTable();
134	+	MeshMakeData data{gd.ndef(), (u16)side, MeshGrid{1}};
135	+	data.m_generate_minimap = false;
136	+	data.m_smooth_lighting = false;
137	+	data.m_enable_water_reflections = false;
138	+	data.m_blockpos = {0, 0, 0};
139	+	for (s16 x = -1; x <= side; x++)
140	+	for (s16 y = -1; y <= side; y++)
141	+	for (s16 z = -1; z <= side; z++)
142	+		data.m_vmanip.setNode({x, y, z}, MapNode(CONTENT_AIR, LIGHT_SUN, 0));
143	+	for (const Placed &p : placed)
144	+		data.m_vmanip.setNode(p.pos, p.node);
145	+
146	+	MeshCollector col{{}};
147	+	MapblockMeshGenerator mg{&data, &col};
148	+	mg.generate();
149	+
150	+	std::vector<Tri> out;
151	+	for (auto &layer : col.prebuffers)
152	+	for (auto &buf : layer) {
153	+		for (size_t i = 0; i + 2 < buf.indices.size(); i += 3) {
154	+			Tri t;
155	+			t.texture = buf.layer.texture_id;
156	+			for (int k = 0; k < 3; k++)
157	+				t.v[k] = buf.vertices.at(buf.indices[i + k]);
158	+			out.push_back(t);
159	+		}
160	+	}
161	+	return out;
162	+}
163	+
164	+v3f triNormal(const Tri &t)
165	+{
166	+	v3f n = (t.v[1].Pos - t.v[0].Pos).crossProduct(t.v[2].Pos - t.v[0].Pos);
167	+	n.normalize();
168	+	return n;
169	+}
170	+
171	+// Is `p` on a triangle drawn with `texture` that faces along `normal`
172	+// (either winding)?
173	+bool covered(const std::vector<Tri> &tris, u32 texture, v3f p, v3f normal)
174	+{
175	+	for (const Tri &t : tris) {
176	+		if (t.texture != texture)
177	+			continue;
178	+		v3f n = triNormal(t);
179	+		if (std::fabs(std::fabs(n.dotProduct(normal)) - 1.0f) > 1e-3f)
180	+			continue;
181	+		if (std::fabs((p - t.v[0].Pos).dotProduct(n)) > 1e-2f)
182	+			continue;
183	+		v3f a = t.v[0].Pos, b = t.v[1].Pos, c = t.v[2].Pos;
184	+		v3f v0 = c - a, v1 = b - a, v2 = p - a;
185	+		f32 d00 = v0.dotProduct(v0), d01 = v0.dotProduct(v1), d02 = v0.dotProduct(v2);
186	+		f32 d11 = v1.dotProduct(v1), d12 = v1.dotProduct(v2);
187	+		f32 den = d00 * d11 - d01 * d01;
188	+		if (std::fabs(den) < 1e-9f)
189	+			continue;
190	+		f32 u = (d11 * d02 - d01 * d12) / den;
191	+		f32 w = (d00 * d12 - d01 * d02) / den;
192	+		if (u >= -1e-4f && w >= -1e-4f && u + w <= 1.0f + 1e-4f)
193	+			return true;
194	+	}
195	+	return false;
196	+}
197	+
198	+// Does the mesh have a face drawn with `texture` facing `outward` that lies in
199	+// the plane through `on_plane`?
200	+bool hasFace(const std::vector<Tri> &tris, u32 texture, v3f on_plane, v3f outward)
201	+{
202	+	for (const Tri &t : tris) {
203	+		if (t.texture != texture)
204	+			continue;
205	+		if (!near(t.v[0].Normal, outward, 1e-3f))
206	+			continue;
207	+		if (std::fabs((t.v[0].Pos - on_plane).dotProduct(outward)) < EPS)
208	+			return true;
209	+	}
210	+	return false;
211	+}
212	+
213	+bool sameBox(const aabb3f &a, const aabb3f &b)
214	+{
215	+	return near(a.MinEdge, b.MinEdge, EPS) && near(a.MaxEdge, b.MaxEdge, EPS);
216	+}
217	+
218	+bool sameBoxes(std::vector<aabb3f> actual, std::vector<aabb3f> expected)
219	+{
220	+	if (actual.size() != expected.size())
221	+		return false;
222	+	for (const aabb3f &e : expected) {
223	+		auto it = std::find_if(actual.begin(), actual.end(),
224	+				[&](const aabb3f &a) { return sameBox(a, e); });
225	+		if (it == actual.end())
226	+			return false;
227	+		actual.erase(it);
228	+	}
229	+	return true;
230	+}
