345	+// Checks a straight row of three panes: along X when `along_x`, along Z otherwise.
346	+void checkGlassRow(bool along_x)
347	+{
348	+	DrawGameDef gd;
349	+	content_t glass = gd.add(glassDef());
350	+	gd.finalize();
351	+
352	+	std::vector<Placed> placed;
353	+	for (s16 i = 0; i < 3; i++)
354	+		placed.push_back({along_x ? v3s16(i, 0, 0) : v3s16(0, 0, i), MapNode(glass)});
355	+	auto tris = render(gd, placed, 3);
356	+
357	+	// u runs along the row, w across it; both faces of the row are checked.
358	+	auto at = [&](float u, float w) {
359	+		return along_x ? v3f(u, 0, w) : v3f(w, 0, u);
360	+	};
361	+	v3f across = along_x ? v3f(0, 0, 1) : v3f(1, 0, 0);
362	+	for (float side : {1.0f, -1.0f}) {
363	+		v3f normal = across * side;
364	+		// no frame where two panes of the row meet
365	+		CHECK_FALSE(covered(tris, 70, at(FRAME_MID, H * side), normal));
366	+		CHECK_FALSE(covered(tris, 70, at(BS - FRAME_MID, H * side), normal));
367	+		CHECK_FALSE(covered(tris, 70, at(BS + FRAME_MID, H * side), normal));
368	+		CHECK_FALSE(covered(tris, 70, at(2 * BS - FRAME_MID, H * side), normal));
369	+		// a frame at both outer ends of the row
370	+		CHECK(covered(tris, 70, at(-FRAME_MID, H * side), normal));
371	+		CHECK(covered(tris, 70, at(2 * BS + FRAME_MID, H * side), normal));
372	+	}
373	+}
