[metadata] {"type": "text", "file": {"filePath": "/app/task/tests/test.patch", "content": "diff --git a/src/unittest/CMakeLists.txt b/src/unittest/CMakeLists.txt\nindex 8a635c8..a8cb144 100644\n--- a/src/unittest/CMakeLists.txt\n+++ b/src/unittest/CMakeLists.txt\n@@ -58,4 +58,6 @@ set (UNITTEST_CLIENT_SRCS\n \t${CMAKE_CURRENT_SOURCE_DIR}/test_irr_gltf_mesh_loader.cpp\n \t${CMAKE_CURRENT_SOURCE_DIR}/test_mesh_compare.cpp\n \t${CMAKE_CURRENT_SOURCE_DIR}/test_keycode.cpp\n+\t${CMAKE_CURRENT_SOURCE_DIR}/test_tile_polygon_offset.cpp\n+\t${CMAKE_CURRENT_SOURCE_DIR}/test_node_drawing.cpp\n \tPARENT_SCOPE)\ndiff --git a/src/unittest/test.cpp b/src/unittest/test.cpp\nindex 8f0eaf8..4dd2640 100644\n--- a/src/unittest/test.cpp\n+++ b/src/unittest/test.cpp\n@@ -15,6 +15,7 @@\n #include \"porting.h\"\n #include \"debug.h\"\n \n+#include <cstdlib>\n #include <iostream>\n \n #include \"catch.h\"\n@@ -274,7 +275,20 @@ bool run_tests(const std::string &module_name)\n \tif (!testmod) {\n \t\trawstream << \"Did not find module, searching Catch tests: \" << module_name << std::endl;\n \t\tCatch::Session session;\n-\t\tsession.configData().testsOrTags.push_back(module_name);\n+\t\tauto &config = session.configData();\n+\t\tconfig.testsOrTags.push_back(module_name);\n+\t\tconfig.skipBenchmarks = true;\n+\t\tconfig.allowZeroTests = true;\n+\t\t// Harvest helper: allow writing a JUnit XML report when selecting\n+\t\t// Catch tests by name/tag via --test-module, so test runs can be\n+\t\t// consumed by external tooling without a GUI/console.\n+\t\tif (const char *junit_out = std::getenv(\"LUANTI_JUNIT_OUT\")) {\n+\t\t\tconfig.reporterSpecifications.emplace_back(\n+\t\t\t\t\t\"junit\",\n+\t\t\t\t\tCatch::Optional<std::string>(std::string(junit_out)),\n+\t\t\t\t\tCatch::Optional<Catch::ColourMode>(),\n+\t\t\t\t\tstd::map<std::string, std::string>{});\n+\t\t}\n \t\tauto catch_test_failures = session.run();\n \t\treturn catch_test_failures == 0;\n \t}\ndiff --git a/src/unittest/test_node_drawing.cpp b/src/unittest/test_node_drawing.cpp\nnew file mode 100755\nindex 0000000..12d3f81\n--- /dev/null\n+++ b/src/unittest/test_node_drawing.cpp\n@@ -0,0 +1,601 @@\n+// Luanti\n+// SPDX-License-Identifier: LGPL-2.1-or-later\n+\n+// Behavioural checks on how nodes are drawn and outlined: the mesh the map\n+// block mesh generator produces for small arrangements of nodes, and the\n+// boxes a node reports for drawing, selection and collision. Every check\n+// looks at the generated geometry (positions, texture coordinates, which\n+// texture a face uses) or at the returned boxes, never at how the code gets\n+// there.\n+\n+#include <catch.h>\n+\n+#include <algorithm>\n+#include <cmath>\n+#include <vector>\n+\n+#include \"dummygamedef.h\"\n+#include \"itemdef.h\"\n+#include \"nodedef.h\"\n+#include \"mapnode.h\"\n+#include \"light.h\"\n+#include \"client/content_mapblock.h\"\n+#include \"client/mapblock_mesh.h\"\n+#include \"client/meshgen/collector.h\"\n+\n+namespace {\n+\n+constexpr float H = BS / 2.0f;\n+constexpr float EPS = 1e-3f;\n+\n+class DrawGameDef : public DummyGameDef {\n+public:\n+\tNodeDefManager *nodes() { return const_cast<NodeDefManager *>(m_nodedef); }\n+\n+\tcontent_t add(const ContentFeatures &f)\n+\t{\n+\t\tItemDefinition itemdef;\n+\t\titemdef.type = ITEM_NODE;\n+\t\titemdef.name = f.name;\n+\t\titemdef.description = f.name;\n+\t\tstatic_cast<IWritableItemDefManager *>(m_itemdef)->registerItem(itemdef);\n+\t\treturn nodes()->set(f.name, f);\n+\t}\n+\n+\tvoid finalize() { nodes()->resolveCrossrefs(); }\n+};\n+\n+void setLightTable()\n+{\n+\tu8 table[LIGHT_SUN + 1] = {\n+\t\t0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,\n+\t\t0x88, 0x99, 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF,\n+\t};\n+\tmemcpy(const_cast<u8 *>(light_decode_table), table, sizeof(table));\n+}\n+\n+bool near(v3f a, v3f b, float tol)\n+{\n+\treturn std::fabs(a.X - b.X) <= tol && std::fabs(a.Y - b.Y) <= tol && std::fabs(a.Z - b.Z) <= tol;\n+}\n+\n+bool near(v2f a, v2f b, float tol)\n+{\n+\treturn std::fabs(a.X - b.X) <= tol && std::fabs(a.Y - b.Y) <= tol;\n+}\n+\n+struct Tri {\n+\tu32 texture;\n+\tvideo::S3DVertex v[3];\n+};\n+\n+struct Placed {\n+\tv3s16 pos;\n+\tMapNode node;\n+};\n+\n+// Generates the mesh of a side x side x side block holding `placed`\n+// (everything else, including a one node border, is air) and returns every\n+// triangle together with the texture it is drawn with.\n+std::vector<Tri> render(DrawGameDef &gd, const std::vector<Placed> &placed, s16 side)\n+{\n+\tsetLightTable();\n+\tMeshMakeData data{gd.ndef(), (u16)side, MeshGrid{1}};\n+\tdata.m_generate_minimap = false;\n+\tdata.m_smooth_lighting = false;\n+\tdata.m_enable_water_reflections = false;\n+\tdata.m_blockpos = {0, 0, 0};\n+\tfor (s16 x = -1; x <= side; x++)\n+\tfor (s16 y = -1; y <= side; y++)\n+\tfor (s16 z = -1; z <= side; z++)\n+\t\tdata.m_vmanip.setNode({x, y, z}, MapNode(CONTENT_AIR, LIGHT_SUN, 0));\n+\tfor (const Placed &p : placed)\n+\t\tdata.m_vmanip.setNode(p.pos, p.node);\n+\n+\tMeshCollector col{{}};\n+\tMapblockMeshGenerator mg{&data, &col};\n+\tmg.generate();\n+\n+\tstd::vector<Tri> out;\n+\tfor (auto &layer : col.prebuffers)\n+\tfor (auto &buf : layer) {\n+\t\tfor (size_t i = 0; i + 2 < buf.indices.size(); i += 3) {\n+\t\t\tTri t;\n+\t\t\tt.texture = buf.layer.texture_id;\n+\t\t\tfor (int k = 0; k < 3; k++)\n+\t\t\t\tt.v[k] = buf.vertices.at(buf.indices[i + k]);\n+\t\t\tout.push_back(t);\n+\t\t}\n+\t}\n+\treturn out;\n+}\n+\n+v3f triNormal(const Tri &t)\n+{\n+\tv3f n = (t.v[1].Pos - t.v[0].Pos).crossProduct(t.v[2].Pos - t.v[0].Pos);\n+\tn.normalize();\n+\treturn n;\n+}\n+\n+// Is `p` on a triangle drawn with `texture` that faces along `normal`\n+// (either winding)?\n+bool covered(const std::vector<Tri> &tris, u32 texture, v3f p, v3f normal)\n+{\n+\tfor (const Tri &t : tris) {\n+\t\tif (t.texture != texture)\n+\t\t\tcontinue;\n+\t\tv3f n = triNormal(t);\n+\t\tif (std::fabs(std::fabs(n.dotProduct(normal)) - 1.0f) > 1e-3f)\n+\t\t\tcontinue;\n+\t\tif (std::fabs((p - t.v[0].Pos).dotProduct(n)) > 1e-2f)\n+\t\t\tcontinue;\n+\t\tv3f a = t.v[0].Pos, b = t.v[1].Pos, c = t.v[2].Pos;\n+\t\tv3f v0 = c - a, v1 = b - a, v2 = p - a;\n+\t\tf32 d00 = v0.dotProduct(v0), d01 = v0.dotProduct(v1), d02 = v0.dotProduct(v2);\n+\t\tf32 d11 = v1.dotProduct(v1), d12 = v1.dotProduct(v2);\n+\t\tf32 den = d00 * d11 - d01 * d01;\n+\t\tif (std::fabs(den) < 1e-9f)\n+\t\t\tcontinue;\n+\t\tf32 u = (d11 * d02 - d01 * d12) / den;\n+\t\tf32 w = (d00 * d12 - d01 * d02) / den;\n+\t\tif (u >= -1e-4f && w >= -1e-4f && u + w <= 1.0f + 1e-4f)\n+\t\t\treturn true;\n+\t}\n+\treturn false;\n+}\n+\n+// Does the mesh have a face drawn with `texture` facing `outward` that lies in\n+// the plane through `on_plane`?\n+bool hasFace(const std::vector<Tri> &tris, u32 texture, v3f on_plane, v3f outward)\n+{\n+\tfor (const Tri &t : tris) {\n+\t\tif (t.texture != texture)\n+\t\t\tcontinue;\n+\t\tif (!near(t.v[0].Normal, outward, 1e-3f))\n+\t\t\tcontinue;\n+\t\tif (std::fabs((t.v[0].Pos - on_plane).dotProduct(outward)) < EPS)\n+\t\t\treturn true;\n+\t}\n+\treturn false;\n+}\n+\n+bool sameBox(const aabb3f &a, const aabb3f &b)\n+{\n+\treturn near(a.MinEdge, b.MinEdge, EPS) && near(a.MaxEdge, b.MaxEdge, EPS);\n+}\n+\n+bool sameBoxes(std::vector<aabb3f> actual, std::vector<aabb3f> expected)\n+{\n+\tif (actual.size() != expected.size())\n+\t\treturn false;\n+\tfor (const aabb3f &e : expected) {\n+\t\tauto it = std::find_if(actual.begin(), actual.end(),\n+\t\t\t\t[&](const aabb3f &a) { return sameBox(a, e); });\n+\t\tif (it == actual.end())\n+\t\t\treturn false;\n+\t\tactual.erase(it);\n+\t}\n+\treturn true;\n+}\n+\n+// ---------------------------------------------------------------- node defs\n+\n+ContentFeatures stoneDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:stone\";\n+\tf.drawtype = NDT_NORMAL;\n+\tf.solidness = 2;\n+\tfor (TileSpec &tile : f.tiles)\n+\t\ttile.layers[0].texture_id = 42;\n+\treturn f;\n+}\n+\n+ContentFeatures glassDef()\n+{\n+\t// Framed glass: the first tile is the frame, the others the glass itself.\n+\tContentFeatures f;\n+\tf.name = \"test:glass\";\n+\tf.drawtype = NDT_GLASSLIKE_FRAMED;\n+\tf.param_type = CPT_LIGHT;\n+\tf.solidness = 0;\n+\tf.visual_solidness = 1;\n+\tf.light_propagates = true;\n+\tf.tiles[0].layers[0].texture_id = 70;\n+\tfor (int i = 1; i < 6; i++)\n+\t\tf.tiles[i].layers[0].texture_id = 71;\n+\treturn f;\n+}\n+\n+ContentFeatures stairDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:stair\";\n+\tf.drawtype = NDT_NODEBOX;\n+\tf.param_type = CPT_LIGHT;\n+\tf.param_type_2 = CPT2_FACEDIR;\n+\tf.solidness = 0;\n+\tf.node_box.type = NODEBOX_FIXED;\n+\tf.node_box.fixed = {\n+\t\taabb3f(-H, -H, -H, H, 0, H),\n+\t\taabb3f(-H, 0, 0, H, H, H),\n+\t};\n+\tf.selection_box = f.node_box;\n+\tfor (TileSpec &tile : f.tiles)\n+\t\ttile.layers[0].texture_id = 60;\n+\treturn f;\n+}\n+\n+ContentFeatures slabDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:slab\";\n+\tf.drawtype = NDT_NODEBOX;\n+\tf.param_type = CPT_LIGHT;\n+\tf.solidness = 0;\n+\tf.node_box.type = NODEBOX_FIXED;\n+\tf.node_box.fixed = {aabb3f(-H, -H, -H, H, 0, H)};\n+\tfor (TileSpec &tile : f.tiles)\n+\t\ttile.layers[0].texture_id = 95;\n+\treturn f;\n+}\n+\n+ContentFeatures railDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:rail\";\n+\tf.drawtype = NDT_RAILLIKE;\n+\tf.param_type = CPT_LIGHT;\n+\tf.solidness = 0;\n+\tf.light_propagates = true;\n+\tf.groups[\"connect_to_raillike\"] = 1;\n+\t// straight, curved, junction, crossing\n+\tfor (int i = 0; i < 4; i++)\n+\t\tf.tiles[i].layers[0].texture_id = 80 + i;\n+\tfor (int i = 4; i < 6; i++)\n+\t\tf.tiles[i].layers[0].texture_id = 83;\n+\treturn f;\n+}\n+\n+ContentFeatures fenceDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:fence\";\n+\tf.drawtype = NDT_FENCELIKE;\n+\tf.param_type = CPT_LIGHT;\n+\tf.solidness = 0;\n+\tf.light_propagates = true;\n+\tfor (TileSpec &tile : f.tiles)\n+\t\ttile.layers[0].texture_id = 90;\n+\treturn f;\n+}\n+\n+ContentFeatures signDef()\n+{\n+\tContentFeatures f;\n+\tf.name = \"test:sign\";\n+\tf.drawtype = NDT_SIGNLIKE;\n+\tf.param_type = CPT_LIGHT;\n+\tf.param_type_2 = CPT2_WALLMOUNTED;\n+\tf.solidness = 0;\n+\tf.walkable = false;\n+\tf.selection_box.reset();\n+\tf.selection_box.type = NODEBOX_WALLMOUNTED;\n+\tfor (TileSpec &tile : f.tiles)\n+\t\ttile.layers[0].texture_id = 50;\n+\treturn f;\n+}\n+\n+// ---------------------------------------------------------------- framed glass\n+\n+constexpr float FRAME_IN = 0.876f * (BS / 2.0f);\n+constexpr float FRAME_MID = (FRAME_IN + H) / 2.0f;\n+\n+// Checks a straight row of three panes: along X when `along_x`, along Z otherwise.\n+void checkGlassRow(bool along_x)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t glass = gd.add(glassDef());\n+\tgd.finalize();\n+\n+\tstd::vector<Placed> placed;\n+\tfor (s16 i = 0; i < 3; i++)\n+\t\tplaced.push_back({along_x ? v3s16(i, 0, 0) : v3s16(0, 0, i), MapNode(glass)});\n+\tauto tris = render(gd, placed, 3);\n+\n+\t// u runs along the row, w across it; both faces of the row are checked.\n+\tauto at = [&](float u, float w) {\n+\t\treturn along_x ? v3f(u, 0, w) : v3f(w, 0, u);\n+\t};\n+\tv3f across = along_x ? v3f(0, 0, 1) : v3f(1, 0, 0);\n+\tfor (float side : {1.0f, -1.0f}) {\n+\t\tv3f normal = across * side;\n+\t\t// no frame where two panes of the row meet\n+\t\tCHECK_FALSE(covered(tris, 70, at(FRAME_MID, H * side), normal));\n+\t\tCHECK_FALSE(covered(tris, 70, at(BS - FRAME_MID, H * side), normal));\n+\t\tCHECK_FALSE(covered(tris, 70, at(BS + FRAME_MID, H * side), normal));\n+\t\tCHECK_FALSE(covered(tris, 70, at(2 * BS - FRAME_MID, H * side), normal));\n+\t\t// a frame at both outer ends of the row\n+\t\tCHECK(covered(tris, 70, at(-FRAME_MID, H * side), normal));\n+\t\tCHECK(covered(tris, 70, at(2 * BS + FRAME_MID, H * side), normal));\n+\t}\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"Framed glass in a row along X is framed only around the outside of the row\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckGlassRow(true);\n+}\n+\n+TEST_CASE(\"Framed glass in a row along Z is framed only around the outside of the row\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckGlassRow(false);\n+}\n+\n+// ---------------------------------------------------------------- turned node boxes\n+\n+namespace {\n+\n+// The stair's upper half sits on the side its facedir points to:\n+// 0 = +Z, 1 = +X, 2 = -Z, 3 = -X.\n+std::vector<aabb3f> expectedStair(int facedir)\n+{\n+\taabb3f lower(-H, -H, -H, H, 0, H);\n+\tswitch (facedir) {\n+\tcase 0: return {lower, aabb3f(-H, 0, 0, H, H, H)};\n+\tcase 1: return {lower, aabb3f(0, 0, -H, H, H, H)};\n+\tcase 2: return {lower, aabb3f(-H, 0, -H, H, H, 0)};\n+\tdefault: return {lower, aabb3f(-H, 0, -H, 0, H, H)};\n+\t}\n+}\n+\n+void checkStair(int facedir)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t stair = gd.add(stairDef());\n+\tgd.finalize();\n+\tconst NodeDefManager *ndef = gd.ndef();\n+\tMapNode n(stair, 0, facedir);\n+\n+\tstd::vector<aabb3f> boxes;\n+\tn.getNodeBoxes(ndef, &boxes);\n+\tCHECK(sameBoxes(boxes, expectedStair(facedir)));\n+\tboxes.clear();\n+\tn.getSelectionBoxes(ndef, &boxes);\n+\tCHECK(sameBoxes(boxes, expectedStair(facedir)));\n+\tboxes.clear();\n+\tn.getCollisionBoxes(ndef, &boxes);\n+\tCHECK(sameBoxes(boxes, expectedStair(facedir)));\n+\n+\t// the drawn mesh shows the upper half on the same side: its top face\n+\t// covers the middle of that quarter of the node, at full height\n+\tauto tris = render(gd, {{v3s16(0, 0, 0), n}}, 1);\n+\taabb3f upper = expectedStair(facedir)[1];\n+\tv3f centre = (upper.MinEdge + upper.MaxEdge) * 0.5f;\n+\tCHECK(covered(tris, 60, v3f(centre.X, H, centre.Z), v3f(0, 1, 0)));\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"A node box turned a quarter turn ends up facing the side its facedir names\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckStair(1);\n+\tcheckStair(3);\n+}\n+\n+TEST_CASE(\"A node box with facedir 0 or 2 faces +Z or -Z\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckStair(0);\n+\tcheckStair(2);\n+}\n+\n+// ---------------------------------------------------------------- node box sides\n+\n+namespace {\n+\n+// A slab next to one full block: the slab's side facing away from the block\n+// is open air and must be drawn.\n+void checkSlabBeside(v3s16 block_dir)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t stone = gd.add(stoneDef());\n+\tcontent_t slab = gd.add(slabDef());\n+\tgd.finalize();\n+\n+\tv3s16 slab_pos(1, 0, 1);\n+\tauto tris = render(gd, {\n+\t\t{slab_pos, MapNode(slab)},\n+\t\t{slab_pos + block_dir, MapNode(stone)},\n+\t}, 3);\n+\n+\tv3f origin = intToFloat(slab_pos, BS);\n+\tv3f away = v3f::from(-block_dir);\n+\tCHECK(hasFace(tris, 95, origin + away * H, away));\n+\t// and its top is drawn as usual\n+\tCHECK(hasFace(tris, 95, origin, v3f(0, 1, 0)));\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"A node box next to a full block on its X sides still draws the open side opposite it\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckSlabBeside(v3s16(-1, 0, 0));\n+\tcheckSlabBeside(v3s16(1, 0, 0));\n+}\n+\n+TEST_CASE(\"A node box next to a full block on its Z sides still draws the open side opposite it\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckSlabBeside(v3s16(0, 0, -1));\n+\tcheckSlabBeside(v3s16(0, 0, 1));\n+}\n+\n+// ---------------------------------------------------------------- rails\n+\n+namespace {\n+\n+// A rail at the middle of a 3x3 patch with rails on the two given sides is a\n+// curve joining those sides. The curved picture, as drawn for a curve joining\n+// +X and -Z, is turned by `angle` degrees about the vertical axis for the\n+// other three curves; every corner of the drawn quad must carry the texture\n+// coordinate that turn gives it.\n+void checkCurve(v3s16 a, v3s16 b, int angle)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t rail = gd.add(railDef());\n+\tgd.finalize();\n+\n+\tv3s16 mid(1, 0, 1);\n+\tauto tris = render(gd, {\n+\t\t{mid, MapNode(rail)}, {mid + a, MapNode(rail)}, {mid + b, MapNode(rail)},\n+\t}, 3);\n+\n+\tconst float y = -H + BS / 64.0f;\n+\tstruct Corner { v3f pos; v2f uv; };\n+\tCorner expected[4] = {\n+\t\t{v3f(-H, y,  H), v2f(0, 0)},\n+\t\t{v3f( H, y,  H), v2f(1, 0)},\n+\t\t{v3f( H, y, -H), v2f(1, 1)},\n+\t\t{v3f(-H, y, -H), v2f(0, 1)},\n+\t};\n+\tv3f origin = intToFloat(mid, BS);\n+\tfor (Corner &c : expected) {\n+\t\tc.pos.rotateXZBy(angle);\n+\t\tc.pos += origin;\n+\t}\n+\n+\tint seen = 0;\n+\tfor (const Tri &t : tris) {\n+\t\tif (t.texture != 81) // the curved tile\n+\t\t\tcontinue;\n+\t\tfor (const video::S3DVertex &v : t.v) {\n+\t\t\tbool ok = false;\n+\t\t\tfor (const Corner &c : expected)\n+\t\t\t\tif (near(v.Pos, c.pos, 1e-2f) && near(v.TCoords, c.uv, 1e-3f))\n+\t\t\t\t\tok = true;\n+\t\t\tCHECK(ok);\n+\t\t\tseen++;\n+\t\t}\n+\t}\n+\tCHECK(seen >= 6);\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"Rail curves joining +X with +Z and -X with -Z are drawn joining those sides\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckCurve(v3s16(1, 0, 0), v3s16(0, 0, 1), 90);\n+\tcheckCurve(v3s16(-1, 0, 0), v3s16(0, 0, -1), 270);\n+}\n+\n+TEST_CASE(\"Rail curves joining +X with -Z and -X with +Z are drawn joining those sides\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckCurve(v3s16(1, 0, 0), v3s16(0, 0, -1), 0);\n+\tcheckCurve(v3s16(-1, 0, 0), v3s16(0, 0, 1), 180);\n+}\n+\n+// ---------------------------------------------------------------- fences\n+\n+namespace {\n+\n+constexpr float POST_RAD = BS / 8.0f;\n+constexpr float BAR_RAD = BS / 16.0f;\n+\n+// Two posts one node apart (along X or Z): the bars join the two posts, at\n+// both bar heights, and nothing sticks out past either post.\n+void checkFencePair(bool along_x)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t fence = gd.add(fenceDef());\n+\tgd.finalize();\n+\n+\tv3s16 second = along_x ? v3s16(1, 0, 0) : v3s16(0, 0, 1);\n+\tauto tris = render(gd, {{v3s16(0, 0, 0), MapNode(fence)}, {second, MapNode(fence)}}, 2);\n+\n+\tint bar_vertices = 0;\n+\tfor (const Tri &t : tris)\n+\tfor (const video::S3DVertex &v : t.v) {\n+\t\tif (std::fabs(v.Pos.Y) > H - 0.1f)\n+\t\t\tcontinue; // posts run the full height; bars do not\n+\t\tbar_vertices++;\n+\t\tfloat along = along_x ? v.Pos.X : v.Pos.Z;\n+\t\tfloat across = along_x ? v.Pos.Z : v.Pos.X;\n+\t\tCHECK(along >= -POST_RAD - EPS);\n+\t\tCHECK(along <= BS + POST_RAD + EPS);\n+\t\tCHECK(std::fabs(across) <= POST_RAD + EPS);\n+\t}\n+\tCHECK(bar_vertices > 0);\n+\n+\tfor (float bar_y : {BS / 4.0f, -BS / 4.0f}) {\n+\t\tv3f mid = along_x ? v3f(H, bar_y + BAR_RAD, 0) : v3f(0, bar_y + BAR_RAD, H);\n+\t\tCHECK(covered(tris, 90, mid, v3f(0, 1, 0)));\n+\t}\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"Two fence posts one node apart along Z are joined by bars only between them\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckFencePair(false);\n+}\n+\n+TEST_CASE(\"Two fence posts one node apart along X are joined by bars only between them\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckFencePair(true);\n+}\n+\n+// ---------------------------------------------------------------- wall-mounted outlines\n+\n+namespace {\n+\n+// The selection box (outline) of a wall-mounted node is a thin plate lying\n+// against the surface it is mounted on.\n+void checkWallmounted(u8 param2)\n+{\n+\tDrawGameDef gd;\n+\tcontent_t sign = gd.add(signDef());\n+\tgd.finalize();\n+\n+\tconst float t = H - BS / 16.0f;\n+\taabb3f expected{v3f()};\n+\tswitch (param2) {\n+\tcase 0: expected = aabb3f(-H, t, -H, H, H, H); break;    // ceiling\n+\tcase 1: expected = aabb3f(-H, -H, -H, H, -t, H); break;  // floor\n+\tcase 2: expected = aabb3f(t, -H, -H, H, H, H); break;    // wall at +X\n+\tcase 3: expected = aabb3f(-H, -H, -H, -t, H, H); break;  // wall at -X\n+\tcase 4: expected = aabb3f(-H, -H, t, H, H, H); break;    // wall at +Z\n+\tdefault: expected = aabb3f(-H, -H, -H, H, H, -t); break; // wall at -Z\n+\t}\n+\n+\tstd::vector<aabb3f> boxes;\n+\tMapNode(sign, 0, param2).getSelectionBoxes(gd.ndef(), &boxes);\n+\tCHECK(sameBoxes(boxes, {expected}));\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"The outline of a node mounted on a +Z or -Z wall lies against that wall\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckWallmounted(4);\n+\tcheckWallmounted(5);\n+}\n+\n+TEST_CASE(\"The outline of a node mounted on an X wall or a floor or a ceiling lies against it\",\n+\t\t\"[node_drawing]\")\n+{\n+\tcheckWallmounted(0);\n+\tcheckWallmounted(1);\n+\tcheckWallmounted(2);\n+\tcheckWallmounted(3);\n+}\ndiff --git a/src/unittest/test_tile_polygon_offset.cpp b/src/unittest/test_tile_polygon_offset.cpp\nnew file mode 100644\nindex 0000000..4cf188e\n--- /dev/null\n+++ b/src/unittest/test_tile_polygon_offset.cpp\n@@ -0,0 +1,198 @@\n+// Luanti\n+// SPDX-License-Identifier: LGPL-2.1-or-later\n+\n+// Depth offsets of a node's tile layers. A node with an overlay draws the\n+// overlay over its base layer at the same position. Nothing may be drawn\n+// closer to the camera than its geometry really is, and nothing may be pushed\n+// behind the nodes around it: either one hides whatever is drawn right on top\n+// of a node (the selection outline, things lying on the node such as a track),\n+// and the overlay must never end up behind its own base layer.\n+//\n+// The checks look only at the SMaterial that a tile layer sets up, either for\n+// a bare TileLayer or for the tiles a node definition produces.\n+\n+#include \"client/tile.h\"\n+#include \"client/texturesource.h\"\n+#include \"client/shader.h\"\n+#include \"nodedef.h\"\n+\n+#include <catch.h>\n+\n+#include <map>\n+#include <string>\n+\n+TEST_CASE(\"TileLayer::applyMaterialOptions configures basic material state \"\n+\t\t\"from material_flags\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\tTileLayer layer;\n+\tlayer.material_flags = MATERIAL_FLAG_BACKFACE_CULLING;\n+\n+\tvideo::SMaterial material;\n+\tlayer.applyMaterialOptions(material, 0);\n+\n+\tCHECK(material.BackfaceCulling == true);\n+\tCHECK(material.TextureLayers[0].TextureWrapU == video::ETC_CLAMP_TO_EDGE);\n+\tCHECK(material.TextureLayers[0].TextureWrapV == video::ETC_CLAMP_TO_EDGE);\n+\tCHECK(material.TextureLayers[1].TextureWrapU == video::ETC_CLAMP_TO_EDGE);\n+\tCHECK(material.TextureLayers[1].TextureWrapV == video::ETC_CLAMP_TO_EDGE);\n+}\n+\n+TEST_CASE(\"TileLayer::applyMaterialOptions leaves a tile's own layer-0 \"\n+\t\t\"polygon offset untouched\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\tTileLayer layer;\n+\tvideo::SMaterial material;\n+\n+\tlayer.applyMaterialOptions(material, /*layer=*/0);\n+\n+\tCHECK(material.PolygonOffsetSlopeScale == 0.0f);\n+\tCHECK(material.PolygonOffsetDepthBias == 0.0f);\n+}\n+\n+TEST_CASE(\"TileLayer::applyMaterialOptions does not push an overlay slot \"\n+\t\t\"toward the camera just because it is layer 1\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\t// An untouched layer-1 slot, as a node without overlays has it.\n+\tTileLayer layer;\n+\tvideo::SMaterial material;\n+\n+\tlayer.applyMaterialOptions(material, /*layer=*/1);\n+\n+\tCHECK(material.PolygonOffsetSlopeScale == 0.0f);\n+\tCHECK(material.PolygonOffsetDepthBias == 0.0f);\n+}\n+\n+namespace {\n+\n+class StubTextureSource : public ITextureSource {\n+\tstd::map<std::string, u32> m_ids;\n+\n+\tu32 idOf(const std::string &name)\n+\t{\n+\t\tauto it = m_ids.find(name);\n+\t\tif (it != m_ids.end())\n+\t\t\treturn it->second;\n+\t\tu32 id = m_ids.size() + 1;\n+\t\tm_ids[name] = id;\n+\t\treturn id;\n+\t}\n+\n+public:\n+\tu32 getTextureId(const std::string &name) override { return idOf(name); }\n+\tstd::string getTextureName(u32 id) override\n+\t{\n+\t\tfor (auto &it : m_ids)\n+\t\t\tif (it.second == id)\n+\t\t\t\treturn it.first;\n+\t\treturn \"\";\n+\t}\n+\tvideo::ITexture *getTexture(u32 id) override { return nullptr; }\n+\tvideo::ITexture *getTexture(const std::string &name, u32 *id = nullptr) override\n+\t{\n+\t\tif (id)\n+\t\t\t*id = idOf(name);\n+\t\treturn nullptr;\n+\t}\n+\tvideo::ITexture *getTextureForMesh(const std::string &name, u32 *id = nullptr) override\n+\t{\n+\t\tif (id)\n+\t\t\t*id = idOf(name);\n+\t\treturn nullptr;\n+\t}\n+\tPalette *getPalette(const std::string &name) override { return nullptr; }\n+\tbool isKnownSourceImage(const std::string &name) override { return true; }\n+\tvideo::SColor getTextureAverageColor(const std::string &name) override\n+\t{\n+\t\treturn video::SColor(255, 255, 255, 255);\n+\t}\n+};\n+\n+class StubShaderSource : public IShaderSource {\n+public:\n+\tShaderInfo getShaderInfo(u32 id) override { return ShaderInfo(); }\n+\tu32 getShader(const std::string &name, MaterialType material_type,\n+\t\t\tNodeDrawType drawtype = NDT_NORMAL) override\n+\t{\n+\t\treturn 1 + (u32)material_type;\n+\t}\n+\tu32 getShaderRaw(const std::string &name, bool blendAlpha = false) override\n+\t{\n+\t\treturn 100;\n+\t}\n+};\n+\n+TextureSettings plainSettings()\n+{\n+\tTextureSettings ts;\n+\tts.leaves_style = LEAVES_FANCY;\n+\tts.world_aligned_mode = WORLDALIGN_DISABLE;\n+\tts.autoscale_mode = AUTOSCALE_DISABLE;\n+\tts.node_texture_size = 16;\n+\tts.translucent_liquids = true;\n+\tts.connected_glass = false;\n+\tts.enable_minimap = false;\n+\treturn ts;\n+}\n+\n+// A plain cube node, with an overlay on every side when `with_overlay`.\n+ContentFeatures cubeNode(bool with_overlay)\n+{\n+\tContentFeatures f;\n+\tf.name = with_overlay ? \"test:dirt_with_grass\" : \"test:dirt\";\n+\tf.drawtype = NDT_NORMAL;\n+\tfor (TileDef &td : f.tiledef)\n+\t\ttd.name = \"test_dirt.png\";\n+\tif (with_overlay) {\n+\t\tfor (TileDef &td : f.tiledef_overlay)\n+\t\t\ttd.name = \"test_grass_overlay.png\";\n+\t}\n+\tStubTextureSource tsrc;\n+\tStubShaderSource ssrc;\n+\tf.updateTextures(&tsrc, &ssrc, nullptr, nullptr, plainSettings());\n+\treturn f;\n+}\n+\n+} // namespace\n+\n+TEST_CASE(\"A node's overlay layer is not drawn closer to the camera than its geometry\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\tContentFeatures f = cubeNode(true);\n+\tfor (int j = 0; j < 6; j++) {\n+\t\tREQUIRE(f.tiles[j].layers[1].texture_id != 0);\n+\t\tvideo::SMaterial overlay;\n+\t\tf.tiles[j].layers[1].applyMaterialOptions(overlay, 1);\n+\t\tCHECK(overlay.PolygonOffsetSlopeScale >= 0.0f);\n+\t\tCHECK(overlay.PolygonOffsetDepthBias >= 0.0f);\n+\t}\n+}\n+\n+TEST_CASE(\"A node's overlay layer is never pushed behind its own base layer\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\tContentFeatures f = cubeNode(true);\n+\tfor (int j = 0; j < 6; j++) {\n+\t\tvideo::SMaterial base, overlay;\n+\t\tf.tiles[j].layers[0].applyMaterialOptions(base, 0);\n+\t\tf.tiles[j].layers[1].applyMaterialOptions(overlay, 1);\n+\t\tCHECK(overlay.PolygonOffsetDepthBias <= base.PolygonOffsetDepthBias);\n+\t\tCHECK(overlay.PolygonOffsetSlopeScale <= base.PolygonOffsetSlopeScale);\n+\t}\n+}\n+\n+TEST_CASE(\"A node without an overlay gets no depth offset on any of its tile layers\",\n+\t\t\"[tile_polygon_offset]\")\n+{\n+\tContentFeatures f = cubeNode(false);\n+\tfor (int j = 0; j < 6; j++) {\n+\t\tfor (int layer = 0; layer < 2; layer++) {\n+\t\t\tvideo::SMaterial m;\n+\t\t\tf.tiles[j].layers[layer].applyMaterialOptions(m, layer);\n+\t\t\tCHECK(m.PolygonOffsetSlopeScale == 0.0f);\n+\t\t\tCHECK(m.PolygonOffsetDepthBias == 0.0f);\n+\t\t}\n+\t}\n+}\n", "numLines": 857, "startLine": 1, "totalLines": 857}}

