416	+	CHECK(sameBoxes(boxes, expectedStair(facedir)));
417	+	boxes.clear();
418	+	n.getSelectionBoxes(ndef, &boxes);
419	+	CHECK(sameBoxes(boxes, expectedStair(facedir)));
420	+	boxes.clear();
421	+	n.getCollisionBoxes(ndef, &boxes);
422	+	CHECK(sameBoxes(boxes, expectedStair(facedir)));
423	+
424	+	// the drawn mesh shows the upper half on the same side: its top face
425	+	// covers the middle of that quarter of the node, at full height
426	+	auto tris = render(gd, {{v3s16(0, 0, 0), n}}, 1);
427	+	aabb3f upper = expectedStair(facedir)[1];
428	+	v3f centre = (upper.MinEdge + upper.MaxEdge) * 0.5f;
429	+	CHECK(covered(tris, 60, v3f(centre.X, H, centre.Z), v3f(0, 1, 0)));
