448	+// ---------------------------------------------------------------- node box sides
449	+
450	+namespace {
451	+
452	+// A slab next to one full block: the slab's side facing away from the block
453	+// is open air and must be drawn.
454	+void checkSlabBeside(v3s16 block_dir)
455	+{
456	+	DrawGameDef gd;
457	+	content_t stone = gd.add(stoneDef());
458	+	content_t slab = gd.add(slabDef());
459	+	gd.finalize();
460	+
461	+	v3s16 slab_pos(1, 0, 1);
462	+	auto tris = render(gd, {
463	+		{slab_pos, MapNode(slab)},
464	+		{slab_pos + block_dir, MapNode(stone)},
465	+	}, 3);
466	+
467	+	v3f origin = intToFloat(slab_pos, BS);
468	+	v3f away = v3f::from(-block_dir);
469	+	CHECK(hasFace(tris, 95, origin + away * H, away));
470	+	// and its top is drawn as usual
471	+	CHECK(hasFace(tris, 95, origin, v3f(0, 1, 0)));
472	+}
473	+
474	+} // namespace
