490	+// ---------------------------------------------------------------- rails
491	+
492	+namespace {
493	+
494	+// A rail at the middle of a 3x3 patch with rails on the two given sides is a
495	+// curve joining those sides. The curved picture, as drawn for a curve joining
496	+// +X and -Z, is turned by `angle` degrees about the vertical axis for the
497	+// other three curves; every corner of the drawn quad must carry the texture
498	+// coordinate that turn gives it.
499	+void checkCurve(v3s16 a, v3s16 b, int angle)
500	+{
501	+	DrawGameDef gd;
502	+	content_t rail = gd.add(railDef());
503	+	gd.finalize();
504	+
505	+	v3s16 mid(1, 0, 1);
506	+	auto tris = render(gd, {
507	+		{mid, MapNode(rail)}, {mid + a, MapNode(rail)}, {mid + b, MapNode(rail)},
508	+	}, 3);
509	+
510	+	const float y = -H + BS / 64.0f;
511	+	struct Corner { v3f pos; v2f uv; };
512	+	Corner expected[4] = {
513	+		{v3f(-H, y,  H), v2f(0, 0)},
514	+		{v3f( H, y,  H), v2f(1, 0)},
515	+		{v3f( H, y, -H), v2f(1, 1)},
516	+		{v3f(-H, y, -H), v2f(0, 1)},
517	+	};
518	+	v3f origin = intToFloat(mid, BS);
519	+	for (Corner &c : expected) {
520	+		c.pos.rotateXZBy(angle);
521	+		c.pos += origin;
522	+	}
523	+
524	+	int seen = 0;
525	+	for (const Tri &t : tris) {
526	+		if (t.texture != 81) // the curved tile
527	+			continue;
528	+		for (const video::S3DVertex &v : t.v) {
529	+			bool ok = false;
530	+			for (const Corner &c : expected)
531	+				if (near(v.Pos, c.pos, 1e-2f) && near(v.TCoords, c.uv, 1e-3f))
532	+					ok = true;
533	+			CHECK(ok);
534	+			seen++;
535	+		}
536	+	}
537	+	CHECK(seen >= 6);
538	+}
539	+
540	+} // namespace
541	+
542	+TEST_CASE("Rail curves joining +X with +Z and -X with -Z are drawn joining those sides",
543	+		"[node_drawing]")
544	+{
545	+	checkCurve(v3s16(1, 0, 0), v3s16(0, 0, 1), 90);
546	+	checkCurve(v3s16(-1, 0, 0), v3s16(0, 0, -1), 270);
547	+}
548	+
549	+TEST_CASE("Rail curves joining +X with -Z and -X with +Z are drawn joining those sides",
550	+		"[node_drawing]")
551	+{
552	+	checkCurve(v3s16(1, 0, 0), v3s16(0, 0, -1), 0);
553	+	checkCurve(v3s16(-1, 0, 0), v3s16(0, 0, 1), 180);
554	+}
555	+
556	+// ---------------------------------------------------------------- fences
557	+
558	+namespace {
559	+
560	+constexpr float POST_RAD = BS / 8.0f;
561	+constexpr float BAR_RAD = BS / 16.0f;
562	+
563	+// Two posts one node apart (along X or Z): the bars join the two posts, at
564	+// both bar heights, and nothing sticks out past either post.
565	+void checkFencePair(bool along_x)
566	+{
567	+	DrawGameDef gd;
568	+	content_t fence = gd.add(fenceDef());
569	+	gd.finalize();
570	+
571	+	v3s16 second = along_x ? v3s16(1, 0, 0) : v3s16(0, 0, 1);
572	+	auto tris = render(gd, {{v3s16(0, 0, 0), MapNode(fence)}, {second, MapNode(fence)}}, 2);
573	+
574	+	int bar_vertices = 0;
575	+	for (const Tri &t : tris)
576	+	for (const video::S3DVertex &v : t.v) {
577	+		if (std::fabs(v.Pos.Y) > H - 0.1f)
578	+			continue; // posts run the full height; bars do not
579	+		bar_vertices++;
580	+		float along = along_x ? v.Pos.X : v.Pos.Z;
581	+		float across = along_x ? v.Pos.Z : v.Pos.X;
582	+		CHECK(along >= -POST_RAD - EPS);
583	+		CHECK(along <= BS + POST_RAD + EPS);
584	+		CHECK(std::fabs(across) <= POST_RAD + EPS);
585	+	}
586	+	CHECK(bar_vertices > 0);
587	+
588	+	for (float bar_y : {BS / 4.0f, -BS / 4.0f}) {
589	+		v3f mid = along_x ? v3f(H, bar_y + BAR_RAD, 0) : v3f(0, bar_y + BAR_RAD, H);
590	+		CHECK(covered(tris, 90, mid, v3f(0, 1, 0)));
591	+	}
592	+}
593	+
594	+} // namespace
595	+
596	+TEST_CASE("Two fence posts one node apart along Z are joined by bars only between them",
597	+		"[node_drawing]")
598	+{
599	+	checkFencePair(false);
600	+}
601	+
602	+TEST_CASE("Two fence posts one node apart along X are joined by bars only between them",
603	+		"[node_drawing]")
604	+{
605	+	checkFencePair(true);
606	+}
