608	+// ---------------------------------------------------------------- wall-mounted outlines
609	+
610	+namespace {
611	+
612	+// The selection box (outline) of a wall-mounted node is a thin plate lying
613	+// against the surface it is mounted on.
614	+void checkWallmounted(u8 param2)
615	+{
616	+	DrawGameDef gd;
617	+	content_t sign = gd.add(signDef());
618	+	gd.finalize();
619	+
620	+	const float t = H - BS / 16.0f;
621	+	aabb3f expected{v3f()};
622	+	switch (param2) {
623	+	case 0: expected = aabb3f(-H, t, -H, H, H, H); break;    // ceiling
624	+	case 1: expected = aabb3f(-H, -H, -H, H, -t, H); break;  // floor
625	+	case 2: expected = aabb3f(t, -H, -H, H, H, H); break;    // wall at +X
626	+	case 3: expected = aabb3f(-H, -H, -H, -t, H, H); break;  // wall at -X
627	+	case 4: expected = aabb3f(-H, -H, t, H, H, H); break;    // wall at +Z
628	+	default: expected = aabb3f(-H, -H, -H, H, H, -t); break; // wall at -Z
629	+	}
630	+
631	+	std::vector<aabb3f> boxes;
632	+	MapNode(sign, 0, param2).getSelectionBoxes(gd.ndef(), &boxes);
633	+	CHECK(sameBoxes(boxes, {expected}));
634	+}
635	+
636	+} // namespace
637	+
638	+TEST_CASE("The outline of a node mounted on a +Z or -Z wall lies against that wall",
639	+		"[node_drawing]")
